const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');menu.textContent='☰'}));document.getElementById('year').textContent=new Date().getFullYear();
document.getElementById('enquiry').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const name=form.elements.name.value.trim();if(!name){form.elements.name.setCustomValidity('Please enter your name.');form.elements.name.reportValidity();return;}const message=`Hi Karate India Academy!\nMy name is ${name}.\nI'm interested in: ${form.elements.interest.value}.\n${form.elements.message.value.trim()}`;window.location.href='https://wa.me/919953767574?text='+encodeURIComponent(message);});document.getElementById('name').addEventListener('input',e=>e.target.setCustomValidity(''));if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('reveal');observer.unobserve(entry.target);}})},{threshold:.12});document.querySelectorAll('.section-head,.academy-copy,.training-grid article,.review-grid article,.gallery-grid a,.visit-heading,.footer-map').forEach(el=>observer.observe(el));}
